 final Runnable ticker=new Runnable(){public void run(){PikaService service=PikaService.instance;String previewReason=service==null?"Connect Pika to test":service.previewUnavailable();if(unlocked)web.evaluateJavascript("if(window.pikaPreviewAvailabilityChanged)pikaPreviewAvailabilityChanged("+JSONObject.quote(previewReason)+")",null);Store s=Store.get(MainActivity.this);boolean keepAwake=unlocked&&(s.restoredPending()||SetupWizard.required(s)||(recorder!=null&&recorder.active()));boolean wasAwake=(getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0;if(keepAwake!=wasAwake){if(keepAwake)getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}boolean busy=service!=null&&service.ble.online&&service.syncing&&!service.ble.deviceBusy;renderSyncProgress(busy,s.syncProgress);boolean connected=service!=null&&service.ble!=null&&service.ble.online;if(unlocked&&(lastPhoneConnected==null||lastPhoneConnected!=connected)){lastPhoneConnected=connected;web.evaluateJavascript("if(window.pikaPhoneConnectionChanged)pikaPhoneConnectionChanged("+connected+")",null);}try{String version=s.libraryVersion();if(unlocked&&!version.equals(lastLibraryVersion)){lastLibraryVersion=version;web.evaluateJavascript("if(window.pikaPhoneLibraryChanged)window.pikaPhoneLibraryChanged("+JSONObject.quote(version)+")",null);}}catch(Exception ignored){}try{String telemetry=s.deviceTelemetry().toString();if(unlocked&&!telemetry.equals(lastDeviceTelemetry)){lastDeviceTelemetry=telemetry;web.evaluateJavascript("if(window.pikaPhoneDeviceChanged)pikaPhoneDeviceChanged("+telemetry+")",null);}}catch(Exception ignored){}boolean paired=DeviceLifecycle.paired(s)||instrumentPreview;statusCard.setVisibility(paired?View.VISIBLE:View.GONE);navigation.setVisibility(unlocked&&paired&&(instrumentPreview||!SetupWizard.required(s))?View.VISIBLE:View.GONE);applyNativeTheme(theme());deviceMetrics.setText(deviceSummary(s));status.setText((service==null?"Disconnected":service.ble.online?"Pika connected":service.status.equals("Pika connected")?"Reconnecting to Pika":service.status)+"\n"+(!backupStatus.isEmpty()?backupStatus:service==null||!service.ble.online?"Phone library available offline":service.ble.deviceBusy?"Pika in use · sync paused":s.syncMessage));ui.postDelayed(this,1000);}};
