 void exportBackup(boolean drive){if(!unlocked||backupPreparing)return;LinearLayout fields=new LinearLayout(this);fields.setOrientation(LinearLayout.VERTICAL);fields.setPadding(32,12,32,8);EditText password=new EditText(this),repeat=new EditText(this);password.setHint("Backup password · at least 10 characters");repeat.setHint("Repeat password");password.setInputType(129);repeat.setInputType(129);fields.addView(password);fields.addView(repeat);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Encrypted complete backup").setMessage("Includes recordings, records, settings and Google/AI credentials. Keep this password: it is required to restore on another phone.").setView(fields).setNegativeButton("Cancel",null).setPositiveButton("Create backup",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(v2->{String value=password.getText().toString();if(value.length()<10||!value.equals(repeat.getText().toString())){password.setError("Use matching passwords of at least 10 characters");return;}dialog.dismiss();exportBackupWithPassword(drive,value.toCharArray());}));dialog.show();}
 void exportBackupWithPassword(boolean drive,char[] password){if(!unlocked||backupPreparing)return;backupPreparing=true;backupStatus="Preparing complete phone backup";requests.execute(()->{File staged=new File(getCacheDir(),"pika-backup-"+System.currentTimeMillis()+".zip");try{try(OutputStream out=new FileOutputStream(staged)){Store store=Store.get(this);PikaService service=PikaService.instance;if(service!=null&&service.ble.online){BleTransport.Reply settings=service.ble.rpc("/api/phone/settings-export","GET",null,null);if(settings.status!=200)throw new IOException("Could not back up device settings");synchronized(store){store.state.put("deviceSecrets",settings.json());store.save();}}PortableBackup.write(store,out,password);Arrays.fill(password,'\0');}ui.post(()->{backupPreparing=false;backupStatus="";backupExport=false;exportFile=staged;exportText=null;String title="pika-backup-"+new java.text.SimpleDateFormat("yyyy-MM-dd-HHmm",Locale.ROOT).format(new Date())+".pika-backup";Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").putExtra(Intent.EXTRA_TITLE,title).addCategory(Intent.CATEGORY_OPENABLE);if(drive){String previous=getPreferences(MODE_PRIVATE).getString("driveLastUri","");if(previous.startsWith("content://com.google.android.apps.docs.storage"))intent.putExtra(android.provider.DocumentsContract.EXTRA_INITIAL_URI,Uri.parse(previous));Toast.makeText(this,"Choose Google Drive and a folder",Toast.LENGTH_LONG).show();}startActivityForResult(intent,drive?44:42);});}catch(Exception error){staged.delete();ui.post(()->{backupPreparing=false;backupStatus="";show("Backup failed: "+error.getMessage());});}finally{Arrays.fill(password,'\0');}});}
