 void applyNativeTheme(String value){if(value.equals(activeTheme))return;activeTheme=value;boolean dark=value.equals("dark");getSharedPreferences("appearance",MODE_PRIVATE).edit().putBoolean("dark",dark).apply();if(Build.VERSION.SDK_INT>=31)getSystemService(UiModeManager.class).setApplicationNightMode(dark?UiModeManager.MODE_NIGHT_YES:UiModeManager.MODE_NIGHT_NO);getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(dark?0xff222320:0xfff6f4ef));navigation.theme(dark);int paper=dark?0xff222320:0xfff6f4ef,muted=dark?0xffb0aca1:0xff77736c;root.setBackgroundColor(paper);web.setBackgroundColor(paper);status.setTextColor(muted);deviceMetrics.setTextColor(muted);getWindow().setStatusBarColor(paper);getWindow().setNavigationBarColor(paper);getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);android.graphics.drawable.GradientDrawable bg=(android.graphics.drawable.GradientDrawable)statusCard.getBackground();bg.setColor(dark?0xff2d2e2a:0xfffdfbf7);bg.setStroke(Math.max(1,(int)getResources().getDisplayMetrics().density),dark?0xff53544b:0xffe5dfd4);syncBar.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(dark?0xff53544b:0xffe5dfd4));web.evaluateJavascript("if(window.pikaApplyTheme)pikaApplyTheme("+JSONObject.quote(value)+")",null);}
 static String deviceSummary(Store store){synchronized(store){JSONObject device=store.state.optJSONObject("snapshot").optJSONObject("device");if(device==null)return "";String battery=device.optBoolean("batteryValid")?String.format(Locale.ROOT,"%d%% %.2fV",device.optInt("batteryPercent"),device.optDouble("batteryMillivolts")/1000):"Battery unavailable";double total=device.optDouble("storageTotal",0),free=device.optDouble("storageFree",0);return battery+"\n"+(total>0?String.format(Locale.ROOT,"%.1f GB/ %.1f GB",free/1073741824d,total/1073741824d):"SD unavailable");}}
