 void download(Uri uri){try{backupExport=false;String n=uri.getQueryParameter("num");if(uri.getPath().equals("/day.txt")){String day=uri.getQueryParameter("date");JSONArray memories=Store.get(this).snapshot().getJSONArray("memories");StringBuilder text=new StringBuilder();for(int i=0;i<memories.length();i++){JSONObject item=memories.getJSONObject(i);if(item.optString("date").startsWith(day))text.append(item.optString("title")).append("\n").append(item.optString("date")).append("\n\n").append(item.optString("text")).append("\n\n----------------\n\n");}exportText=text.toString();exportFile=null;}else{if(n==null)return;Store store=Store.get(this);if(uri.getPath().equals("/wav")){exportFile=memoryAudio(store,n);exportText=null;if(exportFile==null||!exportFile.isFile())throw new IOException("Recording not saved on phone yet");}else{JSONObject memory; synchronized(store){memory=store.find(store.snapshot(),"memories","m"+n);}if(memory==null)throw new IOException("Memory not found");exportFile=null;exportText=memory.optString("text");}}startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(uri.getPath().equals("/wav")?"audio/wav":"text/plain").putExtra(Intent.EXTRA_TITLE,exportFile==null?"pika-day.txt":exportFile.getName()).addCategory(Intent.CATEGORY_OPENABLE),42);}catch(Exception e){show(e.getMessage());}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==41){if(chooser!=null){chooser.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);chooser=null;}return;}if(result!=RESULT_OK||data==null)return;Uri uri=data.getData();final File chosenFile=exportFile;final String chosenText=exportText;final boolean chosenBackup=backupExport;if(request==42||request==44)requests.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(chosenBackup)throw new IOException("Create an encrypted backup first");else if(chosenFile!=null)Files.copy(chosenFile.toPath(),out);else out.write(chosenText.getBytes(StandardCharsets.UTF_8));if(request==44&&uri.getAuthority()!=null&&uri.getAuthority().startsWith("com.google.android.apps.docs.storage"))getPreferences(MODE_PRIVATE).edit().putString("driveLastUri",uri.toString()).apply();ui.post(()->show("Saved"));}catch(Exception e){ui.post(()->show(e.getMessage()));}});if(request==43)restoreBackupUri(uri);}
 void restoreBackupUri(Uri uri){EditText password=new EditText(this);password.setHint("Backup password · leave blank for a legacy ZIP");password.setInputType(129);new AlertDialog.Builder(this).setTitle("Restore backup").setView(password).setNegativeButton("Cancel",null).setPositiveButton("Restore",(d,w)->{char[] secret=password.getText().toString().toCharArray();requests.execute(()->{try(BufferedInputStream in=new BufferedInputStream(getContentResolver().openInputStream(uri))){in.mark(8);byte[] magic=new byte[6];int count=in.read(magic);in.reset();if(count==6&&Arrays.equals(magic,PortableBackup.MAGIC))PortableBackup.restore(Store.get(this),in,secret);else PhoneBackup.restore(Store.get(this),in);ui.post(()->{web.reload();show("Restored. Confirm synchronization before replacing Pika data.");});}catch(Exception e){ui.post(()->show(e.getMessage()));}finally{Arrays.fill(secret,'\0');}});}).show();}
